def pick_unit(L):
    G=H.load_weights(f"model.layers.{L}.mlp.gate_proj.weight");U=H.load_weights(f"model.layers.{L}.mlp.up_proj.weight");D=H.load_weights(f"model.layers.{L}.mlp.down_proj.weight")
    sc=np.linalg.norm(G,axis=1)*np.linalg.norm(U,axis=1)*np.linalg.norm(D,axis=0)
