def build(L,units,a=1.5,off=7,scale=1.0,target=None):
    G=H.load_weights(f"model.layers.{L}.mlp.gate_proj.weight").copy();U=H.load_weights(f"model.layers.{L}.mlp.up_proj.weight").copy();D=H.load_weights(f"model.layers.{L}.mlp.down_proj.weight").copy()
    lnw=H.load_weights(f"model.layers.{L}.post_attention_layernorm.weight")
    tv=target_vec(L,off) if target is None else target
    for which,j in zip(['mid','start'],units):
        g,mh,c=det(L,which)
        S,O,Ol=collect(L); Sg=S[:40] if which=='mid' else S[40:]
        zg=(Sg@g).mean()
        G[j]=a*g; U[j]=mh/c
        delta=tv-stan_resid(L,which)
        D[:,j]=scale*delta/(a*zg)   # SiLU(a z)≈a z for large z
    # note: mlp_in already includes the norm weight, so gate rows act on mlp_in directly
    return {f"model.layers.{L}.mlp.gate_proj.weight":G,f"model.layers.{L}.mlp.up_proj.weight":U,f"model.layers.{L}.mlp.down_proj.weight":D}
